"""Offline exhibition generator; Python standard library only."""
import hashlib
import html
import json
import re
from pathlib import Path
from urllib.parse import quote

ROOT = Path(__file__).resolve().parent
OUT = ROOT / '展览页面'
STYLE = '''body{margin:0;background:#f5f2eb;color:#252525;font-family:"Microsoft YaHei",sans-serif;line-height:1.8}main{max-width:800px;margin:48px auto;padding:28px}h1{line-height:1.4;font-size:2rem}a{color:#305b70}li{margin:20px 0;padding:20px;background:white;border-radius:8px}.author{color:#555}.description{white-space:pre-wrap;overflow-wrap:anywhere;font-size:1.15rem;background:white;padding:24px;border-radius:8px}nav{margin:32px 0}'''

def page(title, body):
    return f'<!doctype html>\n<html lang="zh-CN"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>{html.escape(title)}</title><style>{STYLE}</style></head><body><main>{body}</main></body></html>\n'

def digest(data):
    return hashlib.sha256(data).hexdigest()

def generate():
    # Validate all input before changing any output.
    works = json.loads((ROOT / 'inputs' / 'works.json').read_text(encoding='utf-8-sig'))
    if not isinstance(works, list):
        raise ValueError('works.json 最外层必须是作品列表。')
    pages = {}
    entries = []
    for number, work in enumerate(works, 1):
        if not isinstance(work, dict) or any(not isinstance(work.get(k), str) for k in ('title', 'author', 'description')):
            raise ValueError(f'第 {number} 件作品的 title、author、description 必须都是文字。')
        safe = re.sub(r'[<>:"/\\|?*\x00-\x1f]', '_', work['title']).strip(' .')[:70] or '未命名'
        filename = f'{number:03d}-{safe}.html'
        title, author, description = (html.escape(work[k]) for k in ('title', 'author', 'description'))
        pages[filename] = page(work['title'], f'<nav><a href="index.html">← 返回总目录</a></nav><h1>{title}</h1><p class="author">{author}</p><div class="description">{description}</div>')
        entries.append(f'<li><a href="{quote(filename)}">{title}</a><div class="author">{author}</div></li>')
    pages['index.html'] = page('展览总目录', '<h1>展览总目录</h1><ol>' + ''.join(entries) + '</ol>')
    OUT.mkdir(exist_ok=True)
    manifest = OUT / '.generated.json'
    previous = json.loads(manifest.read_text(encoding='utf-8')) if manifest.exists() else {}
    # Do not overwrite manually changed pages or unrelated files.
    for name in pages:
        path = OUT / name
        if path.exists() and digest(path.read_bytes()) != previous.get(name):
            raise ValueError(f'页面已被手动修改或不是本程序生成：{name}。请先移走该文件再生成。')
    for name, content in pages.items():
        (OUT / name).write_bytes(content.encode('utf-8'))
    for name, old_hash in previous.items():
        if name not in pages and Path(name).name == name and name.endswith('.html'):
            path = OUT / name
            if path.is_file() and digest(path.read_bytes()) == old_hash:
                path.unlink()
    manifest.write_text(json.dumps({name: digest(content.encode('utf-8')) for name, content in pages.items()}, ensure_ascii=False, indent=2), encoding='utf-8')
    print(f'已生成 {len(works)} 件作品和总目录：{OUT / "index.html"}')

if __name__ == '__main__':
    try:
        generate()
    except Exception as error:
        print(f'生成失败：{error}')
        raise SystemExit(1)

